/*
 * QR Code generator — 수업마법사용 번들
 * 기반: qrcodegen (Project Nayuki), MIT License
 * https://www.nayuki.io/page/qr-code-generator-library
 * 
 * 사용법: QRCode.toCanvas(canvasEl, text, {errorCorrectionLevel:'M'})
 *        QRCode.toDataURL(text, {errorCorrectionLevel:'M'}, callback)
 */
var QRCode=(function(){
"use strict";
// ── 갈루아 체 GF(256) ──
var EXP=new Uint8Array(512),LOG=new Uint8Array(256);
(function(){var x=1;for(var i=0;i<255;i++){EXP[i]=x;LOG[x]=i;x<<=1;if(x&256)x^=285;}for(var i=255;i<512;i++)EXP[i]=EXP[i-255];})();
function gmul(a,b){return a&&b?EXP[LOG[a]+LOG[b]]:0;}

// ── RS 생성 다항식 ──
function rsPoly(n){var g=[1];for(var i=0;i<n;i++){var t=[1,EXP[i]],r=new Array(g.length+1).fill(0);for(var a=0;a<g.length;a++)for(var b=0;b<t.length;b++)r[a+b]^=gmul(g[a],t[b]);g=r;}return g;}
function rsCalc(data,n){var g=rsPoly(n),m=[].concat(data,new Array(n).fill(0));for(var i=0;i<data.length;i++){var c=m[i];if(c)for(var j=1;j<g.length;j++)m[i+j]^=gmul(g[j],c);}return m.slice(data.length);}

// ── 버전/용량 테이블 ──
var CAP=[
  null,
  {L:19,M:16,Q:13,H:9},{L:34,M:28,Q:22,H:16},{L:55,M:44,Q:34,H:26},
  {L:80,M:64,Q:48,H:36},{L:108,M:86,Q:62,H:46},{L:136,M:108,Q:76,H:60},
  {L:156,M:124,Q:88,H:66},{L:194,M:154,Q:110,H:86},{L:232,M:182,Q:132,H:100},
  {L:274,M:216,Q:154,H:122},{L:324,M:254,Q:180,H:140},{L:370,M:290,Q:206,H:158},
  {L:428,M:334,Q:244,H:180},{L:461,M:365,Q:261,H:197},{L:523,M:415,Q:295,H:223},
  {L:589,M:453,Q:325,H:253},{L:647,M:507,Q:367,H:283},{L:721,M:563,Q:397,H:313},
  {L:795,M:627,Q:445,H:341},{L:861,M:669,Q:485,H:385}
];
var ECC=[
  null,
  {L:7,M:10,Q:13,H:17},{L:10,M:16,Q:22,H:28},{L:15,M:26,Q:18,H:22},
  {L:20,M:18,Q:26,H:16},{L:26,M:24,Q:18,H:22},{L:18,M:16,Q:24,H:28},
  {L:20,M:18,Q:18,H:26},{L:24,M:22,Q:22,H:26},{L:30,M:22,Q:20,H:24},
  {L:18,M:26,Q:24,H:28},{L:20,M:30,Q:28,H:24},{L:24,M:22,Q:26,H:28},
  {L:26,M:22,Q:24,H:22},{L:30,M:24,Q:20,H:24},{L:22,M:24,Q:30,H:24},
  {L:24,M:28,Q:24,H:30},{L:28,M:28,Q:28,H:28},{L:30,M:26,Q:28,H:28},
  {L:28,M:26,Q:26,H:26},{L:28,M:26,Q:30,H:28}
];
var ALIGN=[
  null,[],[6,18],[6,22],[6,26],[6,30],[6,34],
  [6,22,38],[6,24,42],[6,26,46],[6,28,50],
  [6,30,54],[6,32,58],[6,34,62],[6,26,46,66],[6,26,48,70],
  [6,26,50,74],[6,30,54,78],[6,30,56,82],[6,30,58,86],[6,34,62,86]
];
var ECBITS={L:1,M:0,Q:3,H:2};
var MASKS=[
  function(r,c){return(r+c)%2===0;},
  function(r,c){return r%2===0;},
  function(r,c){return c%3===0;},
  function(r,c){return(r+c)%3===0;},
  function(r,c){return(Math.floor(r/2)+Math.floor(c/3))%2===0;},
  function(r,c){return(r*c)%2+(r*c)%3===0;},
  function(r,c){return((r*c)%2+(r*c)%3)%2===0;},
  function(r,c){return((r+c)%2+(r*c)%3)%2===0;}
];

// ── 데이터 인코딩 ──
function encode(text,ecl){
  var bytes=[];
  for(var i=0;i<text.length;i++){
    var c=text.charCodeAt(i);
    if(c<128){bytes.push(c);}
    else if(c<2048){bytes.push((c>>6)|192,c&63|128);}
    else{bytes.push((c>>12)|224,((c>>6)&63)|128,(c&63)|128);}
  }
  var ver=1;
  for(var v=1;v<=20;v++){if(CAP[v][ecl]>=bytes.length+3){ver=v;break;}}
  if(ver>20)throw new Error('텍스트가 너무 길어요');
  var dc=CAP[ver][ecl],ec=ECC[ver][ecl];
  var bits=[];
  // 바이트 모드
  push(bits,4,4);push(bits,bytes.length,8);
  for(var i=0;i<bytes.length;i++)push(bits,bytes[i],8);
  // 종단
  for(var i=0;i<Math.min(4,dc*8-bits.length);i++)bits.push(0);
  while(bits.length%8)bits.push(0);
  var PAD=[0xEC,0x11];var pi=0;
  while(bits.length<dc*8){push(bits,PAD[pi++%2],8);}
  // 코드워드
  var cw=[];for(var i=0;i<bits.length;i+=8){var b=0;for(var j=0;j<8;j++)b=(b<<1)|bits[i+j];cw.push(b);}
  var rs=rsCalc(cw,ec);
  var all=[].concat(cw,rs);
  var final=[];all.forEach(function(b){for(var i=7;i>=0;i--)final.push((b>>i)&1);});
  return{bits:final,ver:ver};
}
function push(arr,val,n){for(var i=n-1;i>=0;i--)arr.push((val>>i)&1);}

// ── 매트릭스 생성 ──
function buildMatrix(text,ecl){
  var d=encode(text,ecl);
  var ver=d.ver,sz=ver*4+17;
  var mat=[];for(var i=0;i<sz;i++){mat.push(new Int8Array(sz).fill(-1));}

  function setFinder(r,c){
    for(var dr=0;dr<7;dr++)for(var dc=0;dc<7;dc++){
      var dark=(dr===0||dr===6||dc===0||dc===6||(dr>=2&&dr<=4&&dc>=2&&dc<=4));
      mat[r+dr][c+dc]=dark?1:0;
    }
  }
  setFinder(0,0);setFinder(0,sz-7);setFinder(sz-7,0);
  // 세퍼레이터
  for(var i=0;i<8;i++){
    safeSet(mat,7,i,0);safeSet(mat,i,7,0);
    safeSet(mat,7,sz-1-i,0);safeSet(mat,i,sz-8,0);
    safeSet(mat,sz-8,i,0);safeSet(mat,sz-1-i,7,0);
  }
  // 타이밍
  for(var i=8;i<sz-8;i++){
    if(mat[6][i]<0)mat[6][i]=i%2===0?1:0;
    if(mat[i][6]<0)mat[i][6]=i%2===0?1:0;
  }
  // 얼라인먼트
  var ap=ALIGN[ver]||[];
  for(var r=0;r<ap.length;r++)for(var c=0;c<ap.length;c++){
    if((r===0&&c===0)||(r===0&&c===ap.length-1)||(r===ap.length-1&&c===0))continue;
    var row=ap[r],col=ap[c];
    if(mat[row][col]>=0)continue;
    for(var dr=-2;dr<=2;dr++)for(var dc=-2;dc<=2;dc++){
      mat[row+dr][col+dc]=(Math.abs(dr)===2||Math.abs(dc)===2||dr===0&&dc===0)?1:0;
    }
  }
  // 포맷 예약
  var fmtPos=getFormatPos(sz);
  fmtPos.forEach(function(p){if(mat[p[0]][p[1]]<0)mat[p[0]][p[1]]=-2;});
  mat[sz-8][8]=1; // 다크 모듈

  // 데이터 배치
  var bi=0,up=true;
  for(var col=sz-1;col>=1;col-=2){
    if(col===6)col=5;
    for(var row=0;row<sz;row++){
      var r2=up?sz-1-row:row;
      for(var dc=0;dc<=1;dc++){
        var c2=col-dc;
        if(mat[r2][c2]<0)mat[r2][c2]=bi<d.bits.length?d.bits[bi++]:0;
      }
    }
    up=!up;
  }

  // 최적 마스크 선택
  var best=Infinity,bm=null;
  for(var mn=0;mn<8;mn++){
    var m=mat.map(function(r){return new Int8Array(r);});
    applyMask(m,mn,sz,ecl);
    var score=penalty(m,sz);
    if(score<best){best=score;bm=m;}
  }
  return bm;
}

function safeSet(mat,r,c,v){if(r>=0&&r<mat.length&&c>=0&&c<mat[0].length&&mat[r][c]<0)mat[r][c]=v;}

function getFormatPos(sz){
  var p=[];
  for(var i=0;i<=8;i++){if(i!==6){p.push([8,i]);p.push([i,8]);}p.push([8,sz-1-i]);p.push([sz-1-i,8]);}
  return p;
}

function applyMask(mat,mn,sz,ecl){
  var fn=MASKS[mn];
  for(var r=0;r<sz;r++)for(var c=0;c<sz;c++){
    if(mat[r][c]>=0&&fn(r,c))mat[r][c]^=1;
    if(mat[r][c]===-2)mat[r][c]=0;
  }
  // 포맷 정보 쓰기
  var eb=ECBITS[ecl];
  var fd=(eb<<3)|mn,rem=fd<<10;
  for(var i=14;i>=10;i--)if(rem&(1<<i))rem^=0x537<<(i-10);
  var fw=((fd<<10)|rem)^0x5412;
  var p1=[[8,0],[8,1],[8,2],[8,3],[8,4],[8,5],[8,7],[8,8],[7,8],[5,8],[4,8],[3,8],[2,8],[1,8],[0,8]];
  var p2=[[sz-1,8],[sz-2,8],[sz-3,8],[sz-4,8],[sz-5,8],[sz-6,8],[sz-7,8],[8,sz-8],[8,sz-7],[8,sz-6],[8,sz-5],[8,sz-4],[8,sz-3],[8,sz-2],[8,sz-1]];
  for(var i=0;i<15;i++){var bit=(fw>>(14-i))&1;mat[p1[i][0]][p1[i][1]]=bit;mat[p2[i][0]][p2[i][1]]=bit;}
  mat[sz-8][8]=1;
}

function penalty(mat,sz){
  var s=0;
  for(var r=0;r<sz;r++){var rh=1,rv=1;
    for(var c=1;c<sz;c++){
      if(mat[r][c]===mat[r][c-1]){rh++;if(rh===5)s+=3;else if(rh>5)s++;}else rh=1;
      if(mat[c][r]===mat[c-1][r]){rv++;if(rv===5)s+=3;else if(rv>5)s++;}else rv=1;
    }
  }
  for(var r=0;r<sz-1;r++)for(var c=0;c<sz-1;c++)
    if(mat[r][c]===mat[r+1][c]&&mat[r][c]===mat[r][c+1]&&mat[r][c]===mat[r+1][c+1])s+=3;
  return s;
}

// ── Canvas에 그리기 ──
function drawCanvas(canvas,matrix,opts){
  var n=matrix.length;
  var margin=opts.margin!=null?opts.margin:4;
  var total=n+margin*2;
  var mod=Math.floor((opts.size||300)/total);
  if(mod<1)mod=1;
  var px=mod*total;
  canvas.width=canvas.height=px;
  var ctx=canvas.getContext('2d');
  // 배경
  ctx.fillStyle=opts.colorLight||'#ffffff';
  ctx.fillRect(0,0,px,px);
  // 모듈
  ctx.fillStyle=opts.colorDark||'#000000';
  for(var r=0;r<n;r++)for(var c=0;c<n;c++){
    if(matrix[r][c]===1){
      var x=(c+margin)*mod,y=(r+margin)*mod;
      ctx.fillRect(x,y,mod,mod);
    }
  }
}

// ── 공개 API ──
function toCanvas(canvas,text,opts){
  if(typeof opts==='function'){opts={};}
  opts=opts||{};
  var ecl=opts.errorCorrectionLevel||'M';
  ecl=ecl.toUpperCase().charAt(0); // L/M/Q/H
  if(!['L','M','Q','H'].includes(ecl))ecl='M';
  try{
    var mat=buildMatrix(text,ecl);
    drawCanvas(canvas,mat,opts);
    return true;
  }catch(e){throw e;}
}

function toDataURL(text,opts,cb){
  if(typeof opts==='function'){cb=opts;opts={};}
  opts=opts||{};
  var c=document.createElement('canvas');
  try{
    toCanvas(c,text,opts);
    var url=c.toDataURL('image/png');
    if(cb)cb(null,url);
    return url;
  }catch(e){if(cb)cb(e);else throw e;}
}

return{toCanvas:toCanvas,toDataURL:toDataURL};
})();
